private static Map<String, Object> immutableJsonObject(Map<String, Object> value) {
    Objects.requireNonNull(value, "data");
    var normalized = new LinkedHashMap<String, Object>();
    value.forEach((key, item) -> normalized.put(key, immutableJsonValue(item)));
    return Map.copyOf(normalized);
}

private static Object immutableJsonValue(Object value) {
    if (value == null || value instanceof String || value instanceof Boolean) return value;
    if (value instanceof Byte || value instanceof Short || value instanceof Integer
            || value instanceof Long || value instanceof java.math.BigInteger) {
        return ((Number) value).longValue();
    }
    if (value instanceof Float || value instanceof Double || value instanceof java.math.BigDecimal) {
        return ((Number) value).doubleValue();
    }
    if (value instanceof Map<?, ?> map) {
        var normalized = new LinkedHashMap<String, Object>();
        map.forEach((key, item) -> {
            if (!(key instanceof String text)) {
                throw new IllegalArgumentException("JSON object keys must be strings");
            }
            normalized.put(text, immutableJsonValue(item));
        });
        return Map.copyOf(normalized);
    }
    if (value instanceof List<?> list) {
        return list.stream().map(SessionDocument::immutableJsonValue).toList();
    }
    throw new IllegalArgumentException("unsupported JSON value: " + value.getClass().getName());
}

private static void requireSequence(long sequence) {
    if (sequence < 1) throw new IllegalArgumentException("sequence must be positive");
}
